alter table engagement_sends
  add column merchant_name text,
  add column is_control_group boolean not null default false;

comment on column engagement_sends.merchant_name is 'Story P2-4 — denormalized from the sent deal''s merchant at send time (not a foreign key, same reasoning as deal_id/template_id above: this is a log, not a referential-integrity-critical table), so lib/engagementSend.js#lastSentMerchantName can look up "the account''s most-recently-sent deal''s merchant" without re-joining against the deals table (whose contents rotate and are not guaranteed to still contain a past deal_id). Feeds lib/engagementScoring.js''s soft merchant-repetition penalty (RECENT_MERCHANT_PENALTY) — a candidate matching this merchant gets scored down, not hard-excluded (the existing exact-deal_id exclusion in lib/engagementRepetition.js is unchanged).';
comment on column engagement_sends.is_control_group is 'Story P2-5 — denormalized copy of engagement_preferences.is_control_group at send time, so a later opt-out-rate/reply-rate/redemption comparison query can group by this column directly on engagement_sends without an extra join, and so the value reflects what the account''s control-group status actually was at the moment of THIS send (in case is_control_group is ever reassigned/corrected later, which the current single-assignment design does not do, but this keeps the historical record accurate regardless).';
